using App.Repositories;

namespace App;

/// <summary>The in-memory repositories, for tests and for trying the services without a database.</summary>
public class MemoryUnitOfWork : IUnitOfWork
{
    public SqlCustomerRepository Customers { get; } = new MemoryCustomerRepository();
    public SqlCategoryRepository Categories { get; } = new MemoryCategoryRepository();
    public SqlProductRepository Products { get; } = new MemoryProductRepository();
    public SqlOrderRepository Orders { get; } = new MemoryOrderRepository();
    public SqlOrderLineRepository OrderLines { get; } = new MemoryOrderLineRepository();
    public SqlTagRepository Tags { get; } = new MemoryTagRepository();
    public SqlProductTagRepository ProductTags { get; } = new MemoryProductTagRepository();
    public SqlAuditLogRepository AuditLogRows { get; } = new MemoryAuditLogRepository();

    /// <summary>Memory has no transactions: changes are kept as they are made.</summary>
    public Task<T> TransactionAsync<T>(Func<IUnitOfWork, Task<T>> work) => work(this);

    public Task TransactionAsync(Func<IUnitOfWork, Task> work) =>
        TransactionAsync<bool>(async uow =>
        {
            await work(uow);
            return true;
        });
}

