using App.Common;
using App.Entities;

namespace App.Repositories;

/// <summary>Keeps audit_log rows in memory, for tests and for trying the services without a database.</summary>
public class MemoryAuditLogRepository() : SqlAuditLogRepository(null!)
{
    private readonly Dictionary<string, AuditLog> rows = [];

    /// <summary>The key of a row, as a list of its key values.</summary>
    private static object[] KeyOf(AuditLog row) => [row.At, row.Message];

    private static string KeyText(AuditLog row) => string.Join("|", KeyOf(row));

    /// <summary>Orders two keys value by value.</summary>
    private static int Compare(IReadOnlyList<object> a, IReadOnlyList<object> b)
    {
        for (var index = 0; index < a.Count; index++)
        {
            var order = Comparer<object>.Default.Compare(a[index], b[index]);
            if (order != 0) return order;
        }
        return 0;
    }

    private IEnumerable<AuditLog> Visible() =>
        rows.Values.Where(row => true).OrderBy(KeyOf, Comparer<object[]>.Create((a, b) => Compare(a, b)));

    public override Task<Page<AuditLog>> ListAsync(int offset, int limit)
    {
        var rows = Visible().ToList();
        return Task.FromResult(new Page<AuditLog>(rows.Skip(offset).Take(limit).ToList(), rows.Count, offset, limit));
    }
}

