using System.Data.Common;
using App;
using App.Common;
using App.Entities;
using App.Errors;

namespace App.Repositories;

/// <summary>Keeps categories rows in the database, with SQL through ADO.NET. A write joins the transaction already open, or is committed at once.</summary>
public class SqlCategoryRepository(Db db)
{
    /// <summary>The columns every read selects.</summary>
    private const string Columns = "\"id\", \"name\"";

    /// <summary>The row with this primary key, or null.</summary>
    public virtual async Task<Category?> FindByIdAsync(long id)
    {
        return await db.OneAsync("SELECT " + Columns + " FROM \"categories\" WHERE \"id\" = @p1", ToEntity, id);
    }

    /// <summary>At most limit rows from offset, by primary key, and how many there are.</summary>
    public virtual async Task<Page<Category>> ListAsync(int offset, int limit)
    {
        var items = await db.AllAsync("SELECT " + Columns + " FROM \"categories\" ORDER BY \"id\" LIMIT @p1 OFFSET @p2", ToEntity, limit, offset);
        var total = await db.OneAsync("SELECT COUNT(*) FROM \"categories\"", row => row.GetInt64(0));
        return new Page<Category>(items, total, offset, limit);
    }

    /// <summary>The row with this name, or null.</summary>
    public virtual async Task<Category?> FindByNameAsync(string name)
    {
        return await db.OneAsync("SELECT " + Columns + " FROM \"categories\" WHERE \"name\" = @p1", ToEntity, name);
    }

    /// <summary>Stores a new row; the values the database fills are read back.</summary>
    public virtual async Task<Category> InsertAsync(Category entity)
    {
        var names = new List<string>();
        var values = new List<object?>();
        if (entity.Id != default) { names.Add("\"id\""); values.Add(entity.Id); }
        names.Add("\"name\""); values.Add(entity.Name);
        var sql = "INSERT INTO \"categories\" (" + string.Join(", ", names) + ") VALUES (" + Db.Markers(names.Count) + ")";
        try
        {
            return await db.OneAsync(sql + " RETURNING " + Columns, row => Fill(row, entity), values.ToArray())
                ?? throw new InvalidOperationException("The Category just written is not there");
        }
        catch (RefusedException error)
        {
            throw new ConflictException("Category", $"the database refused the change: {error.Message}");
        }
    }

    /// <summary>Stores the changes made to a row read from this repository.</summary>
    public virtual async Task<Category> UpdateAsync(Category entity)
    {
        try
        {
            await db.RunAsync("UPDATE \"categories\" SET \"name\" = @p1 WHERE \"id\" = @p2", entity.Name, entity.Id);
        }
        catch (RefusedException error)
        {
            throw new ConflictException("Category", $"the database refused the change: {error.Message}");
        }
        return await db.OneAsync("SELECT " + Columns + " FROM \"categories\" WHERE \"id\" = @p1", row => Fill(row, entity), entity.Id)
            ?? throw new InvalidOperationException("The Category just written is not there");
    }

    /// <summary>Removes a row read from this repository.</summary>
    public virtual async Task DeleteAsync(Category entity)
    {
        try
        {
            await db.RunAsync("DELETE FROM \"categories\" WHERE \"id\" = @p1", entity.Id);
        }
        catch (RefusedException error)
        {
            throw new ConflictException("Category", $"the database refused the change: {error.Message}");
        }
    }

    /// <summary>The Category of a row read with Columns.</summary>
    private static Category ToEntity(DbDataReader row) => Fill(row, new Category());

    /// <summary>Reads a row selected with Columns into entity.</summary>
    private static Category Fill(DbDataReader row, Category entity)
    {
