        var parent0 = await Factories.AddCategoryAsync(uow, n);
        var row = Factories.NewProduct(1);
        row.CategoryId = parent0.Id;
        var created = await service.CreateProductAsync(row);
        await service.DeleteProductAsync(created.Id, created.Version!.Value);
        await Assert.ThrowsAsync<NotFoundException>(() => service.FindProductAsync(created.Id));
    }
}

