using App;

namespace App.Tests;

/// <summary>The test database: TEST_DATABASE_CONNECTION, or SQLite in memory, created from the schema before every test.</summary>
internal static class TestDatabase
{
    // An in-memory database lives as long as its connection is open
    public static readonly string Connection = Environment.GetEnvironmentVariable("TEST_DATABASE_CONNECTION") ?? "Data Source=:memory:";

    /// <summary>Removes every table, so the database starts empty.</summary>
    private static readonly string[] Drop =
    [
        "DROP TABLE IF EXISTS \"audit_log\"",
        "DROP TABLE IF EXISTS \"product_tags\"",
        "DROP TABLE IF EXISTS \"tags\"",
        "DROP TABLE IF EXISTS \"order_lines\"",
        "DROP TABLE IF EXISTS \"orders\"",
        "DROP TABLE IF EXISTS \"products\"",
        "DROP TABLE IF EXISTS \"categories\"",
        "DROP TABLE IF EXISTS \"customers\"",
    ];

    /// <summary>Creates every table, in an order the database accepts.</summary>
    private static readonly string[] Create =
    [
        "CREATE TABLE \"customers\" (\n  \"id\" INTEGER PRIMARY KEY AUTOINCREMENT,\n  \"email\" VARCHAR(120) NOT NULL,\n  \"password_hash\" TEXT NOT NULL,\n  \"created_at\" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  CONSTRAINT \"uq_customers_email\" UNIQUE (\"email\")\n)",
        "CREATE TABLE \"categories\" (\n  \"id\" INTEGER PRIMARY KEY AUTOINCREMENT,\n  \"name\" VARCHAR(60) NOT NULL,\n  UNIQUE (\"name\")\n)",
        "CREATE TABLE \"products\" (\n  \"id\" INTEGER PRIMARY KEY AUTOINCREMENT,\n  \"category_id\" INTEGER NOT NULL,\n  \"name\" VARCHAR(100) NOT NULL,\n  \"price\" DECIMAL(10, 2) NOT NULL,\n  \"status\" VARCHAR(10) NOT NULL,\n  \"version\" INTEGER NOT NULL DEFAULT 1,\n  \"deleted_at\" DATETIME,\n  CHECK (\"price\" >= 0),\n  CONSTRAINT \"fk_products_category\" FOREIGN KEY (\"category_id\") REFERENCES \"categories\" (\"id\")\n)",
        "CREATE INDEX \"ix_products_status\" ON \"products\" (\"status\")",
        "CREATE INDEX \"ix_products_category_id\" ON \"products\" (\"category_id\")",
        "CREATE TABLE \"orders\" (\n  \"id\" INTEGER PRIMARY KEY AUTOINCREMENT,\n  \"customer_id\" INTEGER NOT NULL,\n  \"placed_at\" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (\"customer_id\") REFERENCES \"customers\" (\"id\")\n)",
        "CREATE TABLE \"order_lines\" (\n  \"order_id\" INTEGER NOT NULL,\n  \"line\" INTEGER NOT NULL,\n  \"product_id\" INTEGER NOT NULL,\n  \"quantity\" INTEGER NOT NULL,\n  PRIMARY KEY (\"order_id\", \"line\"),\n  FOREIGN KEY (\"order_id\") REFERENCES \"orders\" (\"id\") ON DELETE CASCADE,\n  FOREIGN KEY (\"product_id\") REFERENCES \"products\" (\"id\") ON DELETE RESTRICT\n)",
        "CREATE TABLE \"tags\" (\n  \"id\" INTEGER PRIMARY KEY AUTOINCREMENT,\n  \"label\" VARCHAR(30) NOT NULL\n)",
        "CREATE TABLE \"product_tags\" (\n  \"product_id\" INTEGER NOT NULL,\n  \"tag_id\" INTEGER NOT NULL,\n  PRIMARY KEY (\"product_id\", \"tag_id\"),\n  FOREIGN KEY (\"product_id\") REFERENCES \"products\" (\"id\") ON DELETE CASCADE,\n  FOREIGN KEY (\"tag_id\") REFERENCES \"tags\" (\"id\") ON DELETE CASCADE\n)",
        "CREATE TABLE \"audit_log\" (\n  \"at\" DATETIME NOT NULL,\n  \"message\" TEXT NOT NULL\n)",
    ];

    /// <summary>The test database, with every table dropped and created again; on one connection, as MySQL turns its foreign key checks off for the connection that asks.</summary>
    public static async Task<Db> OpenAsync()
    {
        var db = await Database.OpenAsync(Connection);
        foreach (var sql in Drop) await db.RunAsync(sql);
        foreach (var sql in Create) await db.RunAsync(sql);
        return db;
    }
}
